//! Embedded `Script_70.pvf` truth tables generated by `scripts/extract_pvf_truth.py`.
//!
//! Provides PVF-backed monster AI sight/cooldown/drop parameters, projectile ballistic
//! and particle specifications, and dungeon growth / branch-room rosters.

use crate::constants::native_ground_x;
use indexmap::IndexMap;
use serde::Deserialize;
use std::sync::LazyLock;

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PvfDropEntry {
    pub item_id: u32,
    pub name: String,
    pub tone: String,
    pub weight: u32,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PvfThrowAttack {
    pub passive_object: u32,
    pub ptl: String,
    pub throw_frame: u32,
    pub start_offset: [i32; 3],
    pub sound: String,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PvfMonsterTruth {
    pub source: String,
    pub sight: u32,
    pub warlike: u32,
    pub attack_delay_ms: u32,
    pub move_speed: [u32; 2],
    pub width: [u32; 2],
    pub level_range: [u32; 2],
    pub categories: Vec<String>,
    pub ability_multipliers: IndexMap<String, u32>,
    pub throw_attack: Option<PvfThrowAttack>,
    pub drops: Vec<PvfDropEntry>,
}

impl PvfMonsterTruth {
    /// PVF `[sight]` converted from native 640×480 pixels into Core world units.
    pub fn sight_world(&self) -> f64 {
        native_ground_x(f64::from(self.sight))
    }

    /// PVF `[attack delay]` converted from milliseconds to seconds.
    pub fn attack_delay_secs(&self) -> f64 {
        f64::from(self.attack_delay_ms) / 1000.0
    }
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PvfProjectileTruth {
    pub id: u32,
    pub label: String,
    pub obj_source: String,
    pub ptl_source: Option<String>,
    pub destroy_ptl_source: Option<String>,
    pub atk_source: String,
    pub speed_x: i32,
    pub speed_z: i32,
    pub gravity: i32,
    pub angle_deg: i32,
    pub life_ms: u32,
    pub landing_type: String,
    pub piercing_power: u32,
    pub z_sine_amp: i32,
    pub z_sine_deg_per_sec: i32,
    pub destroy_particle_count: u32,
    pub spawn_sub_object: Option<u32>,
    pub damage_bonus: i32,
    pub damage_reaction: String,
    pub hit_wav: String,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PvfBranchRoom {
    pub map_source: String,
    pub roster: IndexMap<String, u32>,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PvfStageTruth {
    pub source: String,
    pub basis_level: u32,
    pub min_level: u32,
    pub exp_scale: f64,
    pub champion_counts: Vec<u32>,
    pub breakable_drops: Vec<PvfDropEntry>,
    pub branch_rooms: Vec<PvfBranchRoom>,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PvfTruthTables {
    pub source_archive: String,
    pub monsters: IndexMap<String, PvfMonsterTruth>,
    pub projectiles: IndexMap<String, PvfProjectileTruth>,
    pub stages: IndexMap<String, PvfStageTruth>,
}

pub static PVF_TRUTH: LazyLock<PvfTruthTables> = LazyLock::new(|| {
    // INFALLIBLE: embedded compile-time JSON generated by scripts/extract_pvf_truth.py
    serde_json::from_str(include_str!("pvf_truth.json"))
        .expect("INFALLIBLE: valid core pvf_truth.json")
});

pub fn monster_truth(kind: &str) -> Option<&'static PvfMonsterTruth> {
    PVF_TRUTH.monsters.get(kind)
}

pub fn projectile_truth(native_object: u32) -> Option<&'static PvfProjectileTruth> {
    PVF_TRUTH.projectiles.get(&native_object.to_string())
}

pub fn stage_truth(stage_id: &str) -> Option<&'static PvfStageTruth> {
    PVF_TRUTH.stages.get(stage_id)
}

/// Deterministically select a drop item from a monster's PVF `[item]` table using weighted roll.
/// Returns `(item_name, tone, gold)` without consuming simulation RNG state.
pub fn pvf_loot_for(
    seed: u32,
    enemy_id: u32,
    enemy_kind: &str,
) -> Option<(&'static str, &'static str, u32)> {
    let truth = monster_truth(enemy_kind)?;
    if truth.drops.is_empty() {
        return None;
    }
    let total_weight: u32 = truth.drops.iter().map(|d| d.weight.max(1)).sum();
    if total_weight == 0 {
        return None;
    }
    let h = crate::hash32(seed, enemy_id);
    let mut roll = (h >> 4) % total_weight;
    let mut chosen = &truth.drops[0];
    for entry in &truth.drops {
        let w = entry.weight.max(1);
        if roll < w {
            chosen = entry;
            break;
        }
        roll -= w;
    }
    let gold = 30 + ((h >> 12) % 45);
    Some((chosen.name.as_str(), chosen.tone.as_str(), gold))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_pvf_truth_monsters_and_projectiles_loaded() {
        let red = monster_truth("goblinRed").expect("goblinRed in pvf_truth");
        assert_eq!(red.sight, 300);
        assert_eq!(red.attack_delay_ms, 3000);
        assert_eq!(
            red.throw_attack.as_ref().map(|t| t.passive_object),
            Some(30047)
        );

        let bomb = projectile_truth(30021).expect("30021 GobFlyBomb in pvf_truth");
        assert_eq!(bomb.speed_x, 300);
        assert_eq!(bomb.speed_z, 200);
        assert_eq!(bomb.gravity, 600);
        assert_eq!(bomb.spawn_sub_object, Some(30022));

        let sub = projectile_truth(30022).expect("30022 GobFlyBombSub in pvf_truth");
        assert_eq!(sub.damage_bonus, 30);
        assert_eq!(sub.damage_reaction, "down");

        let ice = projectile_truth(30057).expect("30057 SeaGabIcicle in pvf_truth");
        assert_eq!(ice.piercing_power, 50);
        assert_eq!(ice.z_sine_amp, 5);
        assert_eq!(ice.z_sine_deg_per_sec, 1600);

        let mw = stage_truth("mirkwood").expect("mirkwood stage truth");
        assert_eq!(mw.basis_level, 4);
        assert!((mw.exp_scale - 1.0).abs() < 1e-6);
        assert!(mw.branch_rooms.len() >= 6);

        let deep = stage_truth("mirkwooddeep").expect("mirkwooddeep stage truth");
        assert_eq!(deep.basis_level, 6);
        assert!((deep.exp_scale - 1.4).abs() < 1e-4);
        assert!(deep.branch_rooms.len() >= 6);
    }

    #[test]
    fn test_pvf_loot_for_uses_per_monster_drop_tables() {
        let mut grunt_items = std::collections::HashSet::new();
        for eid in 1..60 {
            let (name, _tone, gold) = pvf_loot_for(20260915, eid, "grunt").expect("grunt drop");
            grunt_items.insert(name);
            assert!((30..75).contains(&gold));
        }
        assert!(grunt_items.contains("命运硬币"));
        assert!(grunt_items.contains("苎麻花叶"));
        assert!(grunt_items.contains("野生草莓"));

        let mut caster_items = std::collections::HashSet::new();
        for eid in 1..60 {
            let (name, _, _) = pvf_loot_for(20260915, eid, "caster").expect("caster drop");
            caster_items.insert(name);
        }
        assert!(caster_items.contains("投掷石块"));

        let mut boss_items = std::collections::HashSet::new();
        for eid in 1..60 {
            let (name, _, _) = pvf_loot_for(20260915, eid, "lugaruBoss").expect("lugaruBoss drop");
            boss_items.insert(name);
        }
        assert!(boss_items.contains("烤硬的黑面包"));
    }
}
